import { Controller } from "@hotwired/stimulus"

// The Farming Advisor is generated by a background job. While the server answers
// with a "pending" card, re-fetch the frame every few seconds until the advice
// (or the fallback message) arrives. Gives up after a bounded number of tries.
export default class extends Controller {
  static values = {
    interval: { type: Number, default: 2000 },
    attempts: { type: Number, default: 30 }
  }

  connect() {
    this.count = 0
    this.observer = new MutationObserver(() => this.schedule())
    this.observer.observe(this.element, { childList: true, subtree: true })
  }

  disconnect() {
    clearTimeout(this.timer)
    this.observer?.disconnect()
  }

  schedule() {
    clearTimeout(this.timer)
    if (!this.pending() || this.count >= this.attemptsValue) return

    this.timer = setTimeout(() => {
      this.count += 1
      this.element.reload()
    }, this.intervalValue)
  }

  pending() {
    return this.element.querySelector("[data-advisor-poll-target='pending']") !== null
  }
}
